        &lt;button onclick=&quot;processInput()&quot;&gt;Parse &amp; Render&lt;/button&gt;
        &lt;details&gt;
            &lt;summary&gt;View Parsed JSON Data&lt;/summary&gt;
            &lt;pre id=&quot;json-output&quot;&gt;[]&lt;/pre&gt;
        &lt;/details&gt;
