    &lt;script&gt;
        let VF;
        let chordSequence = [];
        let currentIndex = 0;
        const batchSize = 4; // Render 4 chords at a time

        const colorMap = {
            &quot;c&quot;: &quot;#E74C3C&quot;, &quot;d&quot;: &quot;#E67E22&quot;, &quot;e&quot;: &quot;#F1C40F&quot;, 
            &quot;f&quot;: &quot;#2ECC71&quot;, &quot;g&quot;: &quot;#3498DB&quot;, &quot;a&quot;: &quot;#9B59B6&quot;, &quot;b&quot;: &quot;#FF69B4&quot;
        };

        window.onload = function() {
            // Guarantee VexFlow is loaded before assigning
            VF = Vex.Flow;

            // Set up tap-to-advance listener on the notation wrapper
            document.getElementById(&quot;notation-wrapper&quot;).addEventListener(&#39;click&#39;, () =&gt; {
                if (chordSequence.length === 0) return;

                currentIndex += batchSize;
                if (currentIndex &gt;= chordSequence.length) {
                    currentIndex = 0; 
                }
                showNextBatch();
            });

            // Process the default placeholder value on load
            processInput();
        };

        function parseABCToVexFlow(abcString) {
            // Remove spaces and bar lines to simplify parsing
            const cleanStr = abcString.replace(/\s+/g, &#39;&#39;).replace(/\|/g, &#39;&#39;);

            // Match chords like [CEG] or single notes like C, c&#39;
            const matches = cleanStr.match(/\[[a-zA-Z,&#39;]+\]|[a-zA-Z][,&#39;]*/g);
            if (!matches) return [];

            return matches.map(match =&gt; {
                // Extract just the letters, commas, and apostrophes
                const items = match.replace(/\[|\]/g, &#39;&#39;).match(/[a-zA-Z][,&#39;]*/g) || [];

                return items.map(noteItem =&gt; {
                    const noteChar = noteItem.charAt(0);
                    let octave = noteChar === noteChar.toUpperCase() ? 4 : 5; // Base octaves

                    // Adjust octave based on commas (down) or apostrophes (up)
                    const modifiers = noteItem.slice(1);
                    for (let mod of modifiers) {
                        if (mod === &#39;,&#39;) octave--;
                        if (mod === &quot;&#39;&quot;) octave++;
                    }

                    return `${noteChar.toLowerCase()}/${octave}`;
                });
            });
        }

        function renderBatch(chords) {
            const div = document.getElementById(&quot;notation&quot;);
            div.innerHTML = &quot;&quot;; 

            if (chords.length === 0) return;

            // 1. Define the base &quot;un-zoomed&quot; dimensions needed
            const baseWidth = Math.max(250, 80 + (chords.length * 60));
            const baseHeight = 160; 

            // 2. Render at the standard base size
            const renderer = new VF.Renderer(div, VF.Renderer.Backends.SVG);
            renderer.resize(baseWidth, baseHeight);

            const context = renderer.getContext();

            // Draw the stave 
            const stave = new VF.Stave(10, 30, baseWidth - 20);
            stave.addClef(&quot;treble&quot;).setContext(context).draw();

            // Map the parsed arrays into VexFlow StaveNotes
            const notes = chords.map(chordArr =&gt; {
                const staveNote = new VF.StaveNote({ keys: chordArr, duration: &quot;q&quot; });

                // Apply our custom colors
                chordArr.forEach((key, index) =&gt; {
                    const noteName = key.split(&#39;/&#39;)[0];
                    const color = colorMap[noteName] || &quot;#000000&quot;;
                    staveNote.setKeyStyle(index, { fillStyle: color, strokeStyle: color });
                });
                return staveNote;
            });

            // Draw the notes
            const voice = new VF.Voice({ num_beats: chords.length, beat_value: 4 });
            voice.addTickables(notes);
            new VF.Formatter().joinVoices([voice]).format([voice], baseWidth - 40);
            voice.draw(context, stave);

            // 3. THE MAGIC: Use CSS and viewBox to auto-scale the SVG to fit the screen natively
            const svg = div.querySelector(&quot;svg&quot;);
            if (svg) {
                // This tells the browser to proportionally scale the SVG to fit its flex container
                svg.setAttribute(&quot;viewBox&quot;, `0 0 ${baseWidth} ${baseHeight}`);
                svg.style.width = &quot;100%&quot;;
                svg.style.height = &quot;100%&quot;;
            }
        }

        function processInput() {
            const input = document.getElementById(&quot;abc-input&quot;).value;
            chordSequence = parseABCToVexFlow(input);

            // Output JSON for debugging/viewing
            document.getElementById(&quot;json-output&quot;).innerText = JSON.stringify(chordSequence, null, 2);

            currentIndex = 0;
            showNextBatch();
        }

        function showNextBatch() {
            if (chordSequence.length === 0) return;

            let nextBatch = chordSequence.slice(currentIndex, currentIndex + batchSize);

            // Wrap-around logic: If the remaining chords don&#39;t fill a full batch, 
            // pull from the beginning of the array to fill the empty slots.
            if (nextBatch.length &lt; batchSize &amp;&amp; chordSequence.length &gt;= batchSize) {
                const remainder = batchSize - nextBatch.length;
                nextBatch = nextBatch.concat(chordSequence.slice(0, remainder));
            }

            renderBatch(nextBatch);
        }
